"  useEffect(() => {
    const printEnabled = !!business?.business_details?.settings?.print_upi_qr;
    if (!previewReceipt || !printEnabled) {
      setPreviewQrUrl(null);
      setPreviewQrMeta(null);
      return;
    }
    const payeeName = business?.business_name || business?.name || posSettings.receiptHeader || 'SHAHE TEHZEEB RESTAURANT';
    const activeEntry = (backendQrs || []).find(e => String(e.id) === String(posSettings.activeStaticUpiId));

    if (!activeEntry) {
      setPreviewQrUrl(null);
      setPreviewQrMeta(null);
      return;
    }

    let upiUri = "";
    const isUrl = activeEntry.upi_id.startsWith('http://') || activeEntry.upi_id.startsWith('https://') || activeEntry.upi_id.startsWith('upi://');
    if (isUrl) {
      upiUri = activeEntry.upi_id;
    } else if (posSettings.qrMode === 'dynamic') {
      const upiAmount = parseFloat(previewReceipt.total_price || 0).toFixed(2);
      upiUri = `upi://pay?pa=${activeEntry.upi_id}&pn=${encodeURIComponent(payeeName)}&am=${upiAmount}&cu=INR`;
    } else {
      upiUri = `upi://pay?pa=${activeEntry.upi_id}&pn=${encodeURIComponent(payeeName)}&cu=INR`;
    }

    QRCode.toDataURL(upiUri, { margin: 1, width: 140 })
      .then(url => {
        setPreviewQrUrl(url);
        setPreviewQrMeta({ upiId: activeEntry.upi_id, brand: activeEntry.brand, name: activeEntry.name });
      })
      .catch(err => console.error('Failed to generate preview QR:', err));
  }, [previewReceipt, posSettings.qrMode, posSettings.activeStaticUpiId, backendQrs, business]);"

